using System;
using UnityEngine;

namespace GPA.TopDown2D
{
    /// <summary>
    /// Lane and sidewalk positions the game can spawn things at (callout scenes, traffic, peds).
    /// Generated by the map builder: road points sit in the middle of a lane and face the
    /// direction of travel; sidewalk points sit on the pavement.
    /// </summary>
    public sealed class SpawnPoints2D : MonoBehaviour
    {
        [Serializable]
        public struct Point
        {
            public Vector2 Position;
            public float Heading;   // degrees around Z; 0 = facing +Y (north)
        }

        public static SpawnPoints2D Instance { get; private set; }

        public Point[] Road = new Point[0];
        public Point[] Sidewalk = new Point[0];

        private void Awake() => Instance = this;
        private void OnDestroy() { if (Instance == this) Instance = null; }

        /// <summary>A random point between <paramref name="minDistance"/> and <paramref name="maxDistance"/> from <paramref name="from"/>.</summary>
        public bool TryPick(Point[] set, Vector2 from, float minDistance, float maxDistance, out Point point)
        {
            point = default;
            if (set == null || set.Length == 0) return false;
            for (int attempt = 0; attempt < 60; attempt++)
            {
                Point p = set[UnityEngine.Random.Range(0, set.Length)];
                float d = Vector2.Distance(p.Position, from);
                if (d >= minDistance && d <= maxDistance) { point = p; return true; }
            }
            // Fall back to the closest-to-range point rather than failing outright.
            float best = float.MaxValue;
            foreach (Point p in set)
            {
                float d = Mathf.Abs(Vector2.Distance(p.Position, from) - (minDistance + maxDistance) * 0.5f);
                if (d < best) { best = d; point = p; }
            }
            return true;
        }

        public Point Nearest(Point[] set, Vector2 to)
        {
            Point best = default;
            float bestD = float.MaxValue;
            foreach (Point p in set)
            {
                float d = (p.Position - to).sqrMagnitude;
                if (d < bestD) { bestD = d; best = p; }
            }
            return best;
        }
    }
}
